-- Same effect as `php yii migrate` for m261011_110000_sync_locations_with_app and m261011_120000_create_location_release_table.
-- Run AFTER 2026-10-11-remove-states.sql. Back up bt_countries and bt_cities first. Safe to run more than once.
-- Generated from api/migrations/data/locations-app-2026-10-11.json (16 countries, 2103 cities).

SET NAMES utf8mb4;

