-- 4) Release history for Locations > Release to App.
CREATE TABLE IF NOT EXISTS `bt_location_release` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `version` int(11) NOT NULL,
  `file_name` varchar(120) NOT NULL,
  `checksum` char(64) NOT NULL,
  `country_count` int(11) NOT NULL,
  `city_count` int(11) NOT NULL,
  `changes` text DEFAULT NULL,
  `notes` varchar(500) DEFAULT NULL,
  `released_by` int(11) DEFAULT NULL,
  `released_by_name` varchar(150) DEFAULT NULL,
  `released_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx-location-release-version` (`version`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

-- 5) Record both migrations.

-- Check: expect 16 countries and 2103 cities.
SELECT (SELECT COUNT(*) FROM bt_countries) AS countries, (SELECT COUNT(*) FROM bt_cities) AS cities;
